		/** 
		 * Tests creating a new InsuredObject.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a InsuredObject");

			StringBuilder msg = new StringBuilder( "-- Failed to create a InsuredObject" );

			try {            
				InsuredObject entity = InsuredObjectService.getInsuredObjectInstance().createInsuredObject( generateNewEntity() );
				thePrimaryKey = entity.getInsuredObjectId();
				LOGGER.info( "-- Successfully created a InsuredObject with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a InsuredObject. 
		 */
		public InsuredObject testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created InsuredObject" );

			InsuredObject entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read InsuredObject with primary key" );
			msg.append( thePrimaryKey );
			
			InsuredObjectFetchOneSummary fetchOneSummary = new InsuredObjectFetchOneSummary( thePrimaryKey );

			try {
				entity = InsuredObjectService.getInsuredObjectInstance().getInsuredObject( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found InsuredObject " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a InsuredObject.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a InsuredObject." );

			StringBuilder msg = new StringBuilder( "Failed to update a InsuredObject : " );        
			InsuredObject entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created InsuredObject." );

				// for use later on...
				thePrimaryKey = entity.getInsuredObjectId();

				InsuredObjectService proxy = InsuredObjectService.getInsuredObjectInstance();            
				proxy.updateInsuredObject( entity );   

				LOGGER.info( "-- Successfully saved InsuredObject - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a InsuredObject.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created InsuredObject." );

			try{
			    InsuredObject entity = testRead(); 
				InsuredObjectService.getInsuredObjectInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted InsuredObject with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete InsuredObject with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all InsuredObjects.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of InsuredObjects:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all InsuredObject : " );        
			List<InsuredObject> collection  = null;

			try {
				// call the static get method on the InsuredObjectService
				collection = InsuredObjectService.getInsuredObjectInstance().getAllInsuredObject();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					InsuredObject entity = null;            
					Iterator<InsuredObject> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getInsuredObjectId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

